import base64 as _b64
CONVERTER_APP_HTML = _b64.b64decode("").decode("utf-8")

"""
MC Chart Converter API
Converts chart images (SVG, PNG, PDF) to high-resolution PNG.
No city data, no authentication tokens, no sensitive information.
Only accepts image bytes, returns image bytes.
"""
from http.server import HTTPServer, BaseHTTPRequestHandler
import json, base64, io, os

def upscale_png(png_bytes, target_w=2400):
    from PIL import Image, ImageFilter, ImageEnhance
    img = Image.open(io.BytesIO(png_bytes)).convert('RGBA')
    w, h = img.size
    if w >= target_w:
        out = io.BytesIO(); img.save(out,'PNG'); return out.getvalue(), w, h, w
    scale = target_w / w
    new_w, new_h = round(w*scale), round(h*scale)
    step1 = img.resize((w*2, h*2), Image.LANCZOS)
    step2 = step1.resize((new_w, new_h), Image.LANCZOS)
    step3 = step2.filter(ImageFilter.UnsharpMask(radius=1.5, percent=130, threshold=2))
    step4 = ImageEnhance.Contrast(step3).enhance(1.08)
    out = io.BytesIO(); step4.save(out,'PNG',optimize=True)
    return out.getvalue(), w, h, new_w

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a): pass

    def send_cors(self):
        # Allow requests from claude.ai and claudeusercontent.com only
        origin = self.headers.get('Origin','')
        if 'claude.ai' in origin or 'claudeusercontent.com' in origin or 'onrender.com' in origin:
            self.send_header('Access-Control-Allow-Origin', origin)
        else:
            self.send_header('Access-Control-Allow-Origin', 'https://claude.ai')
        self.send_header('Access-Control-Allow-Methods', 'POST,GET,OPTIONS')
        self.send_header('Access-Control-Allow-Headers', 'Content-Type')

    def do_OPTIONS(self):
        self.send_response(200); self.send_cors(); self.end_headers()

    def do_GET(self):
        if self.path == '/app':
            # HTTP Basic Auth for chart converter UI
            import base64 as b64mod
            auth = self.headers.get('Authorization','')
            if auth.startswith('Basic '):
                creds = b64mod.b64decode(auth[6:]).decode('utf-8','ignore')
                _, _, pw = creds.partition(':')
                ok = pw.strip().upper() == os.environ.get('APP_PASSWORD','CBRE')
            else:
                ok = False
            if not ok:
                self.send_response(401)
                self.send_header('WWW-Authenticate','Basic realm="MC Chart Converter"')
                self.send_header('Cache-Control','no-store')
                self.send_cors(); self.end_headers()
                self.wfile.write(b'Unauthorised')
                return
            self.send_response(200)
            self.send_header('Content-Type','text/html; charset=utf-8')
            self.send_header('Cache-Control','no-store')
            self.send_cors(); self.end_headers()
            self.wfile.write(CONVERTER_APP_HTML.encode('utf-8'))
            return
        # Health check
        self.send_response(200)
        self.send_header('Content-Type','application/json')
        self.send_cors(); self.end_headers()
        self.wfile.write(json.dumps({'status':'ready','version':'4.0'}).encode())

    def do_POST(self):
        length = int(self.headers.get('Content-Length',0))
        body = json.loads(self.rfile.read(length)) if length else {}
        try:
            fmt = body.get('format','png').lower()
            raw = base64.b64decode(body['image'])
            png_bytes, sw, sh, out_w = upscale_png(raw)
            result = {
                'image': 'data:image/png;base64,' + base64.b64encode(png_bytes).decode(),
                'src_w': sw, 'src_h': sh, 'out_w': out_w
            }
            self.send_response(200)
            self.send_header('Content-Type','application/json')
            self.send_cors(); self.end_headers()
            self.wfile.write(json.dumps(result).encode())
        except Exception as e:
            self.send_response(500)
            self.send_header('Content-Type','application/json')
            self.send_cors(); self.end_headers()
            self.wfile.write(json.dumps({'error':str(e)}).encode())

port = int(os.environ.get('PORT', 8765))
print(f'MC Chart Converter v4.0 on port {port}')
HTTPServer(('0.0.0.0', port), Handler).serve_forever()
